import { readToolDiscoveryMetadata } from "../../tool/discovery-metadata.js";
import { markTrustedPlatformSource } from "../../tool/platform-source-provenance.js";
import { markTrustedHostToolProvenance } from "../../tool/host-tool-provenance.js";
import { revokeModelRuntimeResolver } from "../runtime/model-transport.js";
import { createExecutorModelRuntimeResolver, loadExecutorModelCatalog, } from "./executor-model-bridge.js";
import { forgetReceivedVeryfrontCloudCatalog, } from "../../provider/veryfront-cloud/catalog-client.js";
import { createExecutorRemoteToolSources } from "./executor-tool-remote-facade.js";
import { createExecutorPersistenceFacades } from "./executor-persistence-bridge.js";
import { readExecutorInitialCheckpoints } from "./executor-checkpoint-state.js";
import { EXECUTOR_TOOL_LIMITS } from "./executor-tool-schema.js";
import { copyPrivateSet, createPrivateSet } from "../../security/private-set.js";
/** Executor-local capability views; cleanup revokes these views, never their shared channel. */
export async function createExecutorRuntimeFacades(options) {
    const { input, channel } = options;
    const projectContextSources = options.projectContextSources
        ? copyPrivateSet(options.projectContextSources, EXECUTOR_TOOL_LIMITS.maxSources)
        : createPrivateSet();
    const lifetime = new AbortController();
    const signal = AbortSignal.any([options.signal, channel.signal, lifetime.signal]);
    const allowedModelIds = new Set(input.grant.models.map((model) => model.id));
    const resolveModelRuntime = await createExecutorModelRuntimeResolver({
        channel,
        allowedModelIds,
        signal,
    });
    let catalogScopeKey;
    const forgetCatalog = () => {
        if (catalogScopeKey)
            forgetReceivedVeryfrontCloudCatalog(catalogScopeKey);
        catalogScopeKey = undefined;
    };
    // The broker loads the served catalog with the run's credentials and returns
    // only the granted models' facts; this executor never holds the credential.
    async function loadModelCatalog(callSignal) {
        signal.throwIfAborted();
        const key = await loadExecutorModelCatalog({
            channel,
            allowedModelIds,
            signal: AbortSignal.any([signal, callSignal]),
        });
        forgetCatalog();
        if (signal.aborted) {
            if (key)
                forgetReceivedVeryfrontCloudCatalog(key);
            signal.throwIfAborted();
        }
        catalogScopeKey = key;
        return key;
    }
    function cleanup() {
        revokeModelRuntimeResolver(resolveModelRuntime);
        lifetime.abort();
        forgetCatalog();
        return Promise.resolve();
    }
    function buildHostTools(source, definitions) {
        const tools = Object.create(null);
        for (const definition of definitions) {
            const alias = input.hostToolAliases?.find((entry) => entry.sourceId === source.id && entry.toolName === definition.name);
            tools[definition.name] = {
                id: definition.name,
                ...(alias ? { ownerAgentId: alias.ownerAgentId, shortName: alias.shortName } : {}),
                title: definition.title,
                description: definition.description,
                discovery: readToolDiscoveryMetadata(definition),
                inputSchemaJson: definition.parameters,
                async execute(args, context) {
                    signal.throwIfAborted();
                    if (!args || typeof args !== "object" || Array.isArray(args)) {
                        throw new TypeError("Invalid executor tool arguments");
                    }
                    return await source.executeTool(definition.name, args, context);
                },
            };
        }
        for (const entry of input.platformHostTools ?? []) {
            const tool = tools[entry.toolName];
            if (entry.sourceId === source.id && tool)
                markTrustedHostToolProvenance(tool);
        }
        return tools;
    }
    function snapshotSourceGrants() {
        const hostIds = new Set(input.grant.hostToolFacadeIds);
        const remoteIds = new Set(input.grant.remoteToolSourceIds);
        const expected = new Set([...hostIds, ...remoteIds]);
        if (expected.size !== hostIds.size + remoteIds.size) {
            throw new TypeError("Ambiguous executor tool source grant");
        }
        for (const id of projectContextSources) {
            if (!expected.has(id))
                throw new TypeError("Project context source is unavailable");
        }
        return { remoteIds, expected };
    }
    try {
        signal.throwIfAborted();
        const { remoteIds, expected } = snapshotSourceGrants();
        const sources = expected.size
            ? await createExecutorRemoteToolSources({
                channel,
                signal,
                limits: options.toolLimits,
                projectContextSources,
            })
            : [];
        if (sources.length !== expected.size ||
            new Set(sources.map((source) => source.id)).size !== expected.size ||
            sources.some((source) => !expected.has(source.id)))
            throw new TypeError("Executor tool sources do not match installation");
        const hostTools = new Map();
        const remoteToolSources = new Map();
        for (const source of sources) {
            if (remoteIds.has(source.id)) {
                if (input.platformToolSourceIds?.includes(source.id))
                    markTrustedPlatformSource(source);
                remoteToolSources.set(source.id, source);
                continue;
            }
            const definitions = await source.listTools({ abortSignal: signal });
            const tools = buildHostTools(source, definitions);
            hostTools.set(source.id, tools);
        }
        const persistence = createExecutorPersistenceFacades({
            ...await readExecutorInitialCheckpoints({
                channel,
                signal,
                capabilityIds: input.capabilities.persistence,
            }),
            channel,
            signal,
            capabilityIds: input.capabilities.persistence,
        });
        const state = input.capabilities.projectSteering || input.capabilities.conversationUserText
            ? (await import("./executor-state-bridge.js")).createExecutorStateFacades({
                channel,
                capabilityIds: {
                    projectSteering: input.capabilities.projectSteering,
                    conversationUserText: input.capabilities.conversationUserText,
                },
                agentId: input.grant.agentId,
                projectId: input.grant.execution.projectId,
                branchId: input.grant.execution.branchId,
                signal,
            })
            : {};
        signal.throwIfAborted();
        return {
            resolveModelRuntime,
            loadModelCatalog,
            hostTools,
            remoteToolSources,
            ...persistence,
            ...state,
            cleanup,
        };
    }
    catch (error) {
        await cleanup();
        throw error;
    }
}
